<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">
    <title>GMG Admin Login</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>*{box-sizing:border-box}body{min-height:100vh;margin:0;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 20% 20%,rgba(42,74,138,.45),transparent 32%),linear-gradient(145deg,#071525,#10243d);font-family:Inter,Arial;color:#102033}.login-card{width:min(440px,100%);padding:34px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:#fff;box-shadow:0 30px 80px rgba(0,0,0,.28)}.logo{display:block;width:220px;max-height:72px;object-fit:contain;margin:0 auto 25px}.login-card h1{margin:0 0 7px;text-align:center;font-size:25px}.login-card p{margin:0 0 25px;text-align:center;color:#667585;font-size:13px}.field{display:grid;gap:7px;margin-bottom:16px}label{font-size:12px;font-weight:700}input{width:100%;padding:12px 13px;border:1px solid #ccd6e0;border-radius:10px;font:inherit}input:focus{outline:0;border-color:#20366c;box-shadow:0 0 0 3px rgba(32,54,108,.10)}button{width:100%;min-height:45px;border:0;border-radius:11px;color:#fff;background:linear-gradient(145deg,#20366c,#2a4a8a);font:inherit;font-weight:750;cursor:pointer;box-shadow:0 9px 22px rgba(32,54,108,.24)}.alert{margin-bottom:16px;padding:12px;border:1px solid #fecdca;border-radius:10px;color:#b42318;background:#fef3f2;font-size:12px}.back{display:block;margin-top:18px;text-align:center;color:#20366c;font-size:12px;text-decoration:none}</style>
</head><body><?= $content ?></body></html>
